import {editorSpreads,placeNewBodyPage,assignExistingCovers} from './page-documents.js?v=20261025-release1';
import {comicConfig,comicDefaults,pageRole,pageSide,MAX_PAGES,MAX_CUTS} from './comic-format.js?v=20261025-release1';
import {pageLabel,duplicatePage,movePages,removePages,publicationChecks,ROLES,folioLabel,setReadingDirection} from './publication-model.js?v=20261025-release1';
import {printFields,fillPrintFields,readPrintFields} from './print-settings.js?v=20261025-release1';
export function setupPublication(api){
 const dialog=document.createElement('dialog');dialog.id='publication';dialog.innerHTML=`<div class="modal-head"><div><h2>페이지 관리</h2><small id="publicationSummary"></small></div><button id="publicationClose" aria-label="페이지 관리 닫기">✕</button></div><nav class="publication-tabs"><button data-tab="pages" aria-selected="true">페이지</button><button data-tab="settings">원고 설정</button><button data-tab="story">대사 목록</button><button data-tab="output">인쇄 출력</button><button id="bindingPreview" class="primary">◇ 3D 제본 미리보기</button></nav><section data-pane="pages"><div class="publication-actions"><button id="pubInsert">＋ 뒤에 추가</button><button id="pubDuplicate">복제</button><button id="pubDelete">삭제</button><button id="pubEarlier">앞으로</button><button id="pubLater">뒤로</button><button id="pubUndo">↶ 실행 취소</button><button id="pubRedo">↷ 다시 실행</button><label>보기<select id="pubView"><option value="grid">페이지 목록</option><option value="spread">두 면 펼침</option></select></label></div><p class="publication-help">클릭: 선택 · Ctrl/⌘: 여러 장 · Shift: 범위 · 더블클릭: 편집 · 드래그: 대상 페이지 앞으로 이동</p><div id="publicationGrid"></div><div class="publication-page-meta"><label>페이지 이름<input id="pubPageName" maxlength="60"></label><label>역할<select id="pubRole">${Object.entries(ROLES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="check"><input id="pubHideFolio" type="checkbox">쪽 번호 숨김</label><button id="pubApplyMeta">정보 적용</button><button id="pubEdit">선택 페이지 편집</button><button id="pubCovers">빈 표지 4면 추가</button><button id="pubAssignCovers" title="전체 페이지 수와 그림을 유지하고 처음 두 면과 마지막 두 면의 역할만 표지로 지정합니다">첫·끝 4면을 표지로</button></div><div id="pubSelection" role="status"></div></section><section data-pane="settings" hidden><form id="publicationSettings"><p id="printSettingsHint"></p><div id="publicationPrintFields"><fieldset><legend>원고 용지 · mm</legend><div class="print-field-grid"><label>용지 가로<input id="pubPaperW" readonly></label><label>용지 세로<input id="pubPaperH" readonly></label><label>재단 가로<input id="pubTrimW" type="number" min="20" step="0.1" required></label><label>재단 세로<input id="pubTrimH" type="number" min="20" step="0.1" required></label><label>도련<input id="pubBleed" type="number" min="0" max="20" step="0.001" required></label><label class="check"><input id="pubGuides" type="checkbox">편집 화면 안내선</label></div></fieldset>${printFields('pub')}<button class="primary" type="submit">원고 설정 적용</button></div></form><div id="printChecks"></div></section><section data-pane="story" hidden><p>대사를 페이지 순서대로 편집합니다. 대사를 수정한 다음 적용하세요.</p><button id="pubStoryApply" class="primary">대사 변경 적용</button><div id="publicationStory"></div></section><section data-pane="output" hidden><div id="publicationOutput"></div></section>`;document.body.append(dialog);
 const $=id=>dialog.querySelector('#'+id);let selected=new Set(),anchor=null,epoch=0,observer,queue=Promise.resolve(),view=null,storyEntries=[];
 const button=document.createElement('button');button.id='publicationOpen';button.textContent='▦ 페이지 관리';button.onclick=()=>open();
 function p(){return api.getProject();}
 function choose(pg,e={}){if(e.shiftKey&&anchor){const a=p().pages.findIndex(x=>x.id===anchor),b=p().pages.indexOf(pg);selected=new Set(p().pages.slice(Math.min(a,b),Math.max(a,b)+1).map(x=>x.id));}else if(e.ctrlKey||e.metaKey){selected.has(pg.id)?selected.delete(pg.id):selected.add(pg.id);}else{selected=new Set([pg.id]);anchor=pg.id;}selection();}
 function selection(){const pages=p().pages.filter(pg=>selected.has(pg.id)),one=pages.length===1?pages[0]:null;dialog.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-pressed',String(selected.has(b.dataset.page))));for(const id of ['pubPageName','pubRole','pubHideFolio','pubApplyMeta'])$(id).disabled=!one;for(const id of ['pubDuplicate','pubDelete','pubEarlier','pubLater','pubEdit'])$(id).disabled=!pages.length;$('pubRole').hidden=p().format!=='comic';$('pubCovers').hidden=$('pubAssignCovers').hidden=p().format!=='comic';$('pubAssignCovers').disabled=p().pages.length<4||p().pages.some(pg=>pageRole(pg)!=='body');$('pubPageName').value=one?.name||'';$('pubRole').value=pageRole(one);$('pubHideFolio').checked=!!one?.hideFolio;$('pubSelection').textContent=pages.length+'페이지 선택'+(one?' · '+(pageSide(p(),one)==='left'?'왼쪽 면':'오른쪽 면'):'');}
 function change(fn){try{api.flushScene?.();api.checkpoint();fn();selected=new Set([...selected].filter(id=>p().pages.some(pg=>pg.id===id)));api.jump(p().activePage);render();}catch(e){api.toast(e.message);}}
 function edit(){const pg=p().pages.find(pg=>selected.has(pg.id));if(pg){dialog.close();api.jump(pg.id);}}
 function card(pg){const b=document.createElement('button');b.className='publication-card';b.dataset.page=pg.id;b.draggable=true;b.title='더블클릭하여 편집';const label=document.createElement('b');label.textContent=pageLabel(p(),pg);const cv=document.createElement('canvas');cv.width=120;cv.height=160;const info=document.createElement('small');info.textContent=p().format==='comic'?`${pageSide(p(),pg)==='left'?'왼쪽':'오른쪽'} · ${folioLabel(p(),pg)}`:'웹툰';b.append(cv,label,info);b.onclick=e=>choose(pg,e);b.ondblclick=()=>{choose(pg);edit();};b.ondragstart=e=>{if(!selected.has(pg.id))choose(pg);e.dataTransfer.setData('application/x-scroll-pages',JSON.stringify([...selected]));e.dataTransfer.effectAllowed='move';};b.ondragover=e=>{if(e.dataTransfer.types.includes('application/x-scroll-pages')){e.preventDefault();b.classList.add('drop-before');}};b.ondragleave=()=>b.classList.remove('drop-before');b.ondrop=e=>{e.preventDefault();b.classList.remove('drop-before');try{const ids=JSON.parse(e.dataTransfer.getData('application/x-scroll-pages'));if(!ids.includes(pg.id))change(()=>movePages(p(),ids,pg.id));}catch{}};observer.observe(b);return b;}
 function render(){if(!dialog.open)return;const project=p();view??=project.format==='comic'?'spread':'grid';$('pubView').value=view;selected=new Set([...selected].filter(id=>project.pages.some(pg=>pg.id===id)));if(!selected.size)selected.add(project.activePage);const token=++epoch;observer?.disconnect();$('publicationSummary').textContent=`${project.format==='comic'?'출판만화':'웹툰'} · ${project.pages.length}페이지 · ${project.width} × ${project.pageHeight}px · ${project.dpi}dpi${project.format==='comic'?' · '+(comicDefaults(project.comic).binding==='right'?'우철 · 오른쪽 → 왼쪽':'좌철 · 왼쪽 → 오른쪽'):''}`;$('bindingPreview').disabled=project.format!=='comic';
  observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;observer.unobserve(entry.target);const b=entry.target,pg=project.pages.find(x=>x.id===b.dataset.page);queue=queue.catch(()=>{}).then(async()=>{if(token!==epoch||!dialog.open)return;const cv=await api.renderPage(pg,220,project.format==='comic'?'trim':'paper');if(token!==epoch||!dialog.open){cv.width=1;return;}b.querySelector('canvas').replaceWith(cv);}).catch(e=>{b.title='미리보기 오류: '+e.message;});}},{root:$('publicationGrid'),rootMargin:'180px'});
  const grid=$('publicationGrid');grid.dir=project.format==='comic'&&comicDefaults(project.comic).binding==='right'?'rtl':'ltr';grid.replaceChildren();grid.classList.toggle('spreads',view==='spread');if(view==='spread'&&project.format==='comic'){for(const spread of editorSpreads(project)){const row=document.createElement('div');row.className='publication-spread';for(const side of ['left','right']){if(spread[side])row.append(card(spread[side]));else{const blank=document.createElement('span');blank.className='publication-blank';blank.textContent='빈 면';row.append(blank);}}grid.append(row);}}else project.pages.forEach(pg=>grid.append(card(pg)));selection();settings();if(!dialog.querySelector('[data-pane="story"]').hidden)story();else storyEntries=[];}
 function settings(){const project=p(),c=comicDefaults(project.comic);$('publicationPrintFields').hidden=project.format!=='comic';$('printSettingsHint').textContent=project.format==='comic'?'원본 그림 크기는 유지합니다. 재단·여백·제본 설정만 변경합니다. 용지 크기·해상도는 새 캔버스에서 지정하세요.':'웹툰은 세로 페이지를 사용합니다. 출판용 원고는 새 캔버스 → 출판만화에서 만드세요.';for(const [id,key]of [['pubPaperW','paperWidthMm'],['pubPaperH','paperHeightMm'],['pubTrimW','trimWidthMm'],['pubTrimH','trimHeightMm'],['pubBleed','bleedMm']])$(id).value=c[key];$('pubGuides').checked=c.showGuides;fillPrintFields($('publicationSettings'),c);const issues=publicationChecks(project);$('printChecks').replaceChildren();if(project.format==='comic'){const heading=document.createElement('h3');heading.textContent='제본 전 확인';$('printChecks').append(heading);for(const text of issues.length?issues:['페이지 수·여백·대사 상자 검사에서 확인 항목이 없습니다.']){const el=document.createElement('p');el.textContent=text;$('printChecks').append(el);}}}
 function commitStory(){const dirty=storyEntries.filter(({ta,b})=>!ta.disabled&&ta.value!==(b.text||''));if(dirty.length){api.checkpoint();for(const {ta,b}of dirty)b.text=ta.value;api.render();api.save();}}
 function story(){storyEntries=[];const root=$('publicationStory');root.replaceChildren();let count=0;for(const pg of p().pages){const bubbles=p().cuts.filter(c=>c.pageId===pg.id).flatMap(c=>(c.bubbles||[]).map(b=>({c,b})));if(!bubbles.length)continue;const section=document.createElement('section'),h=document.createElement('h3');h.textContent=pageLabel(p(),pg);section.append(h);for(const {c,b}of bubbles){const label=document.createElement('label'),ta=document.createElement('textarea');label.textContent=`${c.name} · 대사 ${++count}`;ta.value=b.text||'';ta.rows=3;ta.disabled=!!c.layerSettings?.text?.locked||!!c.balloonLayers?.find(l=>l.id===b.balloonLayerId)?.locked;storyEntries.push({ta,b});label.append(ta);section.append(label);}root.append(section);}if(!count)root.textContent='아직 대사가 없습니다. 텍스트·말풍선 도구로 추가하면 여기에 표시됩니다.';}
 async function tab(name){commitStory();dialog.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===name)));dialog.querySelectorAll('[data-pane]').forEach(s=>s.hidden=s.dataset.pane!==name);if(name==='story')story();if(name==='settings')settings();if(name==='output'){try{const {setupPrintOutput}=await import('./print-export.js?v=20261025-release1');setupPrintOutput($('publicationOutput'),{...api,getProject:p,selected:()=>[...selected]});}catch(e){api.toast(e.message);}}}
 function open(initialTab='pages'){if(!p().pages)return api.toast('새 캔버스로 만든 페이지 원고에서 사용할 수 있습니다.');api.flushScene?.();api.closeScene();selected=new Set([p().activePage]);anchor=p().activePage;if(!dialog.open)dialog.showModal();tab(initialTab);render();}
 $('publicationClose').onclick=()=>{commitStory();dialog.close();};$('pubStoryApply').onclick=()=>{commitStory();api.toast('대사를 적용했습니다.');};dialog.addEventListener('close',()=>{commitStory();storyEntries=[];epoch++;observer?.disconnect();for(const cv of $('publicationGrid').querySelectorAll('canvas'))cv.width=1;});
 dialog.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('pubView').onchange=e=>{view=e.target.value;render();};$('pubEdit').onclick=edit;
 $('pubInsert').onclick=()=>change(()=>{if(p().pages.length>=MAX_PAGES)throw Error(`${MAX_PAGES}페이지까지 지원합니다.`);const after=p().pages.findLast(pg=>selected.has(pg.id)),pg=api.makePage(p());placeNewBodyPage(p(),pg,after?.id);selected=new Set([pg.id]);});
 $('pubDuplicate').onclick=()=>change(()=>{const originals=p().pages.filter(pg=>selected.has(pg.id));if(p().pages.length+originals.length>MAX_PAGES||p().cuts.length+p().cuts.filter(c=>selected.has(c.pageId)).length>MAX_CUTS)throw Error('페이지 수 한도를 넘습니다.');const ids=originals.map(pg=>duplicatePage(p(),pg.id).id);selected=new Set(ids);});
 $('pubDelete').onclick=()=>{if(selected.size>=p().pages.length)return api.toast('한 페이지는 남겨야 합니다.');change(()=>removePages(p(),[...selected]));};
 $('pubEarlier').onclick=()=>{const i=p().pages.findIndex(pg=>selected.has(pg.id));if(i>0)change(()=>movePages(p(),[...selected],p().pages[i-1].id));};
 $('pubLater').onclick=()=>{const i=p().pages.findLastIndex(pg=>selected.has(pg.id));if(i<p().pages.length-1)change(()=>movePages(p(),[...selected],p().pages[i+2]?.id||null));};
 $('pubUndo').onclick=()=>{api.undo();render();};$('pubRedo').onclick=()=>{api.redo();render();};
 $('pubApplyMeta').onclick=()=>{const name=$('pubPageName').value,role=$('pubRole').value,hideFolio=$('pubHideFolio').checked;change(()=>{const pg=p().pages.find(pg=>selected.has(pg.id));if(pg)Object.assign(pg,{name,role,hideFolio});});};

 $('pubAssignCovers').onclick=()=>change(()=>assignExistingCovers(p()));
 $('pubCovers').onclick=()=>{if(p().pages.some(pg=>pageRole(pg)!=='body'))return api.toast('이미 표지가 있습니다. 페이지 역할에서 조정하세요.');change(()=>{if(p().pages.length+4>MAX_PAGES)throw Error('표지 4면을 추가할 공간이 없습니다.');const covers=['front','front-inside','back-inside','back'].map(role=>{const pg=api.makePage(p());pg.role=role;return pg;});const body=p().pages.filter(pg=>!covers.includes(pg));p().pages=[...covers.slice(0,2),...body,...covers.slice(2)];});};
 $('publicationSettings').querySelector('[data-print-setting=binding]').addEventListener('change',e=>{$('publicationSettings').querySelector('[data-print-setting=firstSide]').value=e.target.value==='right'?'left':'right';});
 $('publicationSettings').onsubmit=e=>{e.preventDefault();try{const c=comicConfig({...p(),comic:{...p().comic,...readPrintFields($('publicationSettings')),trimWidthMm:+$('pubTrimW').value,trimHeightMm:+$('pubTrimH').value,bleedMm:+$('pubBleed').value,showGuides:$('pubGuides').checked}}).comic;change(()=>p().comic=c);api.toast('원고 설정을 적용했습니다.');}catch(e){api.toast(e.message);}};
 async function preview(){commitStory();api.flushScene?.();api.closeScene();try{const {openBindingPreview}=await import('./binding-preview.js?v=20261025-release1');await openBindingPreview({...api,getProject:p,onManage:name=>open(name),setBinding:binding=>{change(()=>setReadingDirection(p(),binding));api.toast(binding==='right'?'일본 만화 기준: 우철 · 첫 본문 왼쪽으로 적용했습니다.':'좌철 · 첫 본문 오른쪽으로 적용했습니다.');}});}catch(e){api.toast('제본 미리보기: '+e.message);}}
 $('bindingPreview').onclick=preview;

 dialog.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select'))return;if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'){e.preventDefault();e.stopPropagation();(e.shiftKey?api.redo:api.undo)();render();}else if(e.key==='Delete'&&!dialog.querySelector('[data-pane="pages"]').hidden){e.preventDefault();e.stopPropagation();$('pubDelete').click();}});
 return {button,open,preview};
}
